def min_number_of_primes(n, m):
    # Step 1: first m primes (the 1000th prime is 7919, so sieving to 8000 is enough)
    LIMIT = 8000
    is_prime = [True] * (LIMIT + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(LIMIT ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, LIMIT + 1, i):
                is_prime[j] = False
    primes = [i for i in range(2, LIMIT + 1) if is_prime[i]][:m]
    coins = [p for p in primes if p <= n]       # larger primes can never be used

    # Step 2: unbounded coin change, dp[s] = min primes summing to s
    INF = float('inf')
    dp = [0] + [INF] * n
    for s in range(1, n + 1):
        for p in coins:
            if p > s:
                break
            if dp[s - p] + 1 < dp[s]:
                dp[s] = dp[s - p] + 1
    return dp[n] if dp[n] != INF else -1
